C++<pre><code>vector&lt;int&gt; v = {1, 2, 3, 4, 5};

// 删除所有偶数 - 正确方式
for (auto it = v.begin(); it != v.end();) {
    if (*it % 2 == 0) {
        it = v.erase(it);  // erase返回下一个有效迭代器
    } else {
        ++it;
    }
}

// set/map的删除
set&lt;int&gt; s = {1, 2, 3, 4, 5};
for (auto it = s.begin(); it != s.end();) {
    if (*it % 2 == 0) {
        it = s.erase(it);
    } else {
        ++it;
    }
}
</code></pre>

