for (auto it = v.begin(); it != v.end(); ++it) {
    if (*it == 3) {
        v.erase(it);  // 错误! it失效了
        // ++it;      // 错误! 对失效迭代器操作
    }
}

// 错误: 拷贝开销大
vector&lt;string&gt; v = {"long string 1", "long string 2"};
for (auto x : v) {           // 错误! 发生拷贝
    cout &lt;&lt; x &lt;&lt; endl;
}
// 正确
for (const auto&amp; x : v) {    // 正确! 使用引用
    cout &lt;&lt; x &lt;&lt; endl;
}
</code></pre>
